public class ReportTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + expected + " but got " + actual);
            failures++;
        }
    }

    public static void main(String[] args) {
        Circle unit = new Circle(1.0);
        check("circle name", "circle", unit.name());
        check("circle(1.0) area rounded to 2 places", 3.14, Math.round(unit.area() * 100.0) / 100.0);
        Circle bigger = new Circle(1.5);
        check("circle(1.5) area rounded to 2 places", 7.07, Math.round(bigger.area() * 100.0) / 100.0);
        Shape square = new Shape() {
            public double area() { return 4.0; }
            public String name() { return "square"; }
        };
        check("summary of one circle", "circle: 3.14", Report.summary(new Shape[]{ unit }));
        check("summary mixes any Shape implementation (newline shown as \\n)", "circle: 3.14\\nsquare: 4.00", Report.summary(new Shape[]{ unit, square }).replace("\n", "\\n"));
        check("summary pads to two decimals", "square: 4.00", Report.summary(new Shape[]{ square }));
        check("summary of an empty array", "", Report.summary(new Shape[0]));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

